using Amazon.Runtime;
using Amazon.S3;
using Amazon.S3.Model;
using Microsoft.Extensions.Configuration;

namespace Excellore.Access.Infrastructure;

public interface IAuditExportObjectStore
{
    Task PutAsync(string key, byte[] data, CancellationToken cancellationToken);
    Task<byte[]?> GetAsync(string key, CancellationToken cancellationToken);
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}

/// <summary>Private S3-compatible object storage; keys are generated by the worker.</summary>
public sealed class S3AuditExportObjectStore : IAuditExportObjectStore, IDisposable
{
    private readonly AmazonS3Client client;
    private readonly string bucket;
    private readonly bool localDevelopment;
    private const int MaxBytes = 64 * 1024 * 1024;

    public S3AuditExportObjectStore(IConfiguration configuration)
    {
        var endpoint = configuration["AuditExportStore:Endpoint"];
        var accessKey = configuration["AuditExportStore:AccessKey"];
        var secretKey = configuration["AuditExportStore:SecretKey"];
        bucket = configuration["AuditExportStore:Bucket"] ?? "excellore-audit-exports";
        localDevelopment = string.Equals(configuration["EXCELLORE_INSECURE_LOCAL_DEV"],
            "true", StringComparison.OrdinalIgnoreCase);
        if (!Uri.TryCreate(endpoint, UriKind.Absolute, out var uri) ||
            (uri.Scheme != Uri.UriSchemeHttps &&
                !(localDevelopment && uri.Scheme == Uri.UriSchemeHttp &&
                  uri.Host is "127.0.0.1" or "localhost")) ||
            uri.UserInfo.Length > 0 || uri.AbsolutePath != "/" ||
            !string.IsNullOrEmpty(uri.Query) || !string.IsNullOrEmpty(uri.Fragment) ||
            string.IsNullOrWhiteSpace(accessKey) || string.IsNullOrWhiteSpace(secretKey))
            throw new ArgumentException("Audit export object store configuration is invalid.");
        client = new AmazonS3Client(new BasicAWSCredentials(accessKey, secretKey),
            new AmazonS3Config { ServiceURL = uri.GetLeftPart(UriPartial.Authority),
                ForcePathStyle = true, AuthenticationRegion = "us-east-1" });
    }

    public async Task PutAsync(string key, byte[] data, CancellationToken cancellationToken)
    {
        ValidateKey(key);
        if (data.Length is 0 or > MaxBytes)
            throw new InvalidOperationException("Audit export size is invalid.");
        using var stream = new MemoryStream(data, writable: false);
        var request = new PutObjectRequest
        {
            BucketName = bucket, Key = key, ContentType = "application/x-ndjson",
            InputStream = stream
        };
        try
        {
            await client.PutObjectAsync(request, cancellationToken);
        }
        catch (AmazonS3Exception error) when (localDevelopment &&
            error.ErrorCode is "NoSuchBucket" or "NotFound")
        {
            await client.PutBucketAsync(new PutBucketRequest { BucketName = bucket },
                cancellationToken);
            stream.Position = 0;
            await client.PutObjectAsync(request, cancellationToken);
        }
    }

    public async Task<byte[]?> GetAsync(string key, CancellationToken cancellationToken)
    {
        ValidateKey(key);
        try
        {
            using var response = await client.GetObjectAsync(bucket, key, cancellationToken);
            if (response.ContentLength > MaxBytes) return null;
            using var buffer = new MemoryStream();
            var chunk = new byte[64 * 1024];
            int read;
            while ((read = await response.ResponseStream.ReadAsync(chunk, cancellationToken)) > 0)
            {
                if (buffer.Length + read > MaxBytes) return null;
                await buffer.WriteAsync(chunk.AsMemory(0, read), cancellationToken);
            }
            return buffer.ToArray();
        }
        catch (AmazonS3Exception error) when (error.ErrorCode is "NoSuchKey" or "NotFound")
        {
            return null;
        }
    }

    public async Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        ValidateKey(key);
        await client.DeleteObjectAsync(bucket, key, cancellationToken);
    }

    private static void ValidateKey(string key)
    {
        if (!key.StartsWith("audit-exports/", StringComparison.Ordinal) ||
            !key.EndsWith(".jsonl", StringComparison.Ordinal) ||
            !Guid.TryParseExact(key[14..^6], "D", out _))
            throw new ArgumentException("Audit export object key is invalid.");
    }

    public void Dispose() => client.Dispose();
}
